"use client";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { auth, db } from "@/lib/firebase";
import { createUserWithEmailAndPassword, GoogleAuthProvider,signInWithPopup  } from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import Link from "next/link";

export default function SignUp() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const router = useRouter();

const handleSignup = async (e) => {
  e.preventDefault();

  try {
    const userCredential = await createUserWithEmailAndPassword(
      auth,
      email,
      password
    );

    await setDoc(doc(db, "users", userCredential.user.uid), {
      name,
      email,
      createdAt: new Date(),
    });

    router.replace("/");
    router.refresh();
  } catch (error) {
    alert(error.message);
  }
  };
  const handleGoogleSignUp = async () => {
  try {
    const provider = new GoogleAuthProvider();

    const result = await signInWithPopup(auth, provider);

    const user = result.user;

    // Lưu user vào Firestore (merge để không ghi đè)
    await setDoc(
      doc(db, "users", user.uid),
      {
        name: user.displayName,
        email: user.email,
        createdAt: new Date(),
      },
      { merge: true }
    );

    // Redirect về trang chủ
    router.replace("/");
    router.refresh();

  } catch (error) {
    alert(error.message);
  }
  };
  return (
    <div className="text-black">
    <div style={{ minHeight: "100vh", display: "flex", justifyContent: "center", alignItems: "center" }}>

      <div style={{ width: "540px", padding: "40px", background: "white", borderRadius: "10px" }}>

        <h1 style={{ textAlign: "center", fontSize: "38px", color: "#000000", marginBottom: "20px" }}>Đăng kí</h1>

        <form onSubmit={handleSignup} style={{ display: "flex", flexDirection: "column", gap: "20px" }}>

          <input
            color="#000000"
            type="text"
            placeholder="Enter your Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ padding: "20px", borderRadius: "8px", border: "1px solid #000000" }}
          />

          <input
            color="#000000"
            type="email"
            placeholder="Enter your Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{ padding: "20px", borderRadius: "8px", border: "1px solid #000000" }}
          />

          <input
            color="#000000"
            type="password"
            placeholder="Enter your Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ padding: "20px", borderRadius: "8px", border: "1px solid #000000" }}
          />

          <button
            color="#000000"
            
            type="button"
            onClick={handleSignup}
            style={{ padding: "14px", background: "black", color: "white", borderRadius: "8px", border: "none", cursor: "pointer" }}
          >
            Sign Up
          </button>
          <button
            type="button"
            onClick={handleGoogleSignUp}
            style={{padding: "14px",background: "white",color: "black",borderRadius: "8px",border: "1px solid black",cursor: "pointer"}}> Sign Up with Google</button>

        </form>

        <div style={{ textAlign: "center", marginTop: "20px" }}>
          Already have an account?{" "}
          <Link href="/login">Đăng nhập</Link>
        </div>

      </div>
    </div>
    </div>
  );
}